export class Ship {
  constructor(length, coordinates) {
    this.shipLength = length;
    this.isSunk = false;
    this.hits = 0;
    this.coordinates = coordinates;
  }
  hit() {
    if (this.hits === this.shipLength - 1) {
      this.isSunk = true;
      return;
    }
    this.hits += 1;
  }
}

export class gameBoard {
  constructor() {
    this.board = Array.from({ length: 10 }, () => Array(10).fill(false));
    this.boardIds = Array.from({ length: 10 }, () => Array(10).fill(null));
    this.shipSunks = 0;
    this.numShips = 0;
    this.shipCoordinates = [];
  }
  placeShip(length, coordinates) {
    const ship = new Ship(length, coordinates);
    for (let [x, y] of ship.coordinates) {
      if (this.board[x][y] === false) {
        this.board[x][y] = [x, y];
        this.boardIds[x][y] = ship;
        this.shipCoordinates.push([x, y]);
      } else return `Coordinate specified overlapped x: ${x} y: ${y}`;
    }
    this.numShips += 1;
  }
  receiveAttack(coordinates) {
    const [x, y] = coordinates;
    if (this.board[x][y] !== true) {
      if (this.boardIds[x][y]) this.boardIds[x][y].hit();
      this.board[x][y] = true;
    }
    if (this.boardIds[x][y]) {
      if (this.boardIds[x][y].isSunk) this.shipSunks += 1;
    }
  }
  resetBoard() {
    this.board = Array.from({ length: 10 }, () => Array(10).fill(false));
    this.boardIds = Array.from({ length: 10 }, () => Array(10).fill(null));
    this.shipSunks = 0;
    this.numShips = 0;
  }
}

export class Player {
  constructor(name) {
    this.gameBoard = new gameBoard();
    this.name = name;
  }
  placeShip(length, coordinates) {
    this.gameBoard.placeShip(length, coordinates);
  }
  receiveAttack(coordinates) {
    this.gameBoard.receiveAttack(coordinates);
  }
  numShips() {
    return this.gameBoard.numShips;
  }
  shipSunks() {
    return this.gameBoard.shipSunks;
  }
  shipIds() {
    return this.gameBoard.boardIds;
  }
  resetBoard() {
    return this.gameBoard.resetBoard();
  }
  board() {
    return this.gameBoard.board;
  }
}
