import { Player } from "./game";
import "./style.css";

class gameController {
  constructor() {
    this.player1 = new Player("Player 1");
    this.player2 = new Player("Computer");
    this.currentPlayer = this.player1;
    this.container = document.getElementById("container");
    this.computerAttacks = [];
  }
  createBoard(board, id) {
    const boardContainer = document.createElement("div");
    const bContainer = document.createElement("div");
    boardContainer.classList = id;
    if (board.name === "Player 1") {
      const buttonContainer = document.createElement("div");
      const restartGame = document.createElement("button");
      const generateShips = document.createElement("button");
      generateShips.addEventListener("click", (ev) => {
        this.resetBoard();
      });
      restartGame.addEventListener("click", (ev) => {
        this.resetBoard();
      });
      generateShips.textContent = "New Ship Placement";
      restartGame.textContent = "Restart Game";
      buttonContainer.append(generateShips, restartGame);

      boardContainer.append(buttonContainer);
    }

    const coordinates = this.generateShips();

    for (let b of coordinates) {
      board.placeShip(b.length, b);
    }

    for (let x = 0; x < board.board().length; x++) {
      const yContainer = document.createElement("div");
      for (let y = 0; y < 10; y++) {
        const xContainer = document.createElement("div");
        xContainer.classList.add(`grid-${x}${y}`);
        if (board.board()[x][y] !== false && this.currentPlayer === board) {
          xContainer.classList.add("ship");
        }

        xContainer.addEventListener("click", (ev) => {
          if (this.attack(board, x, y, xContainer)) {
            this.attack(board, x, y, xContainer);
          } else this.computerAttack();
        });

        yContainer.append(xContainer);
      }
      bContainer.append(yContainer);
    }
    boardContainer.append(bContainer);
    this.container.append(boardContainer);
  }
  computerAttack() {
    let x = Math.floor(Math.random() * 10);
    let y = Math.floor(Math.random() * 10);
    let coord = `${x}${y}`;
    while (this.computerAttacks.includes(coord)) {
      x = Math.floor(Math.random() * 10);
      y = Math.floor(Math.random() * 10);
      coord = `${x}${y}`;
    }
    this.computerAttacks.push(coord);

    while (
      this.attack(
        this.player1,
        x,
        y,
        document.querySelector(".p1-container").querySelector(`.grid-${coord}`),
        document.querySelector(".p1-container")
      )
    ) {
      while (this.computerAttacks.includes(coord)) {
        x = Math.floor(Math.random() * 10);
        y = Math.floor(Math.random() * 10);
        coord = `${x}${y}`;
      }
      this.computerAttacks.push(coord);
      this.attack(
        this.player1,
        x,
        y,
        document.querySelector(".p1-container").querySelector(`.grid-${coord}`),
        document.querySelector(".p1-container")
      );
    }
  }
  generateShips() {
    const boardSize = 10;
    const shipsLength = [5, 4, 3, 3, 2];
    const placedShips = [];
    const takenCoords = new Set();

    function isValid(coords) {
      return coords.every(
        ([x, y]) =>
          x >= 0 &&
          x < boardSize &&
          y >= 0 &&
          y < boardSize &&
          !takenCoords.has(`${x},${y}`)
      );
    }

    function markTaken(coords) {
      coords.forEach(([x, y]) => takenCoords.add(`${x},${y}`));
    }

    for (let length of shipsLength) {
      let placed = false;

      while (!placed) {
        const isHorizontal = Math.random() < 0.5;
        const x = Math.floor(
          Math.random() * (isHorizontal ? boardSize : boardSize - length)
        );
        const y = Math.floor(
          Math.random() * (isHorizontal ? boardSize - length : boardSize)
        );

        const coords = Array.from({ length }, (_, i) =>
          isHorizontal ? [x, y + i] : [x + i, y]
        );

        if (isValid(coords)) {
          placedShips.push(coords);
          markTaken(coords);
          placed = true;
        }
      }
    }
    return placedShips;
  }

  attack(board, x, y, xContainer) {
    if (this.currentPlayer === board) return;
    if (board.board()[x][y] !== true) {
      board.receiveAttack([x, y]);
      if (board.shipIds()[x][y]) {
        xContainer.classList.add("hit");
        if (board.shipSunks() === board.numShips()) {
          document.querySelectorAll(".game-overlay").forEach((ev) => {
            ev.classList.add("active");
            ev.querySelectorAll("#winner").forEach((ev) => {
              ev.textContent = `Winner is ${this.currentPlayer.name}`;
            });
            ev.querySelector("button").addEventListener("click", (e) => {
              ev.classList.remove("active");
            });
          });
          this.resetBoard();
          return;
        }
        return true;
      } else {
        xContainer.classList.add("miss");
        this.currentPlayer =
          this.currentPlayer === this.player1 ? this.player2 : this.player1;
      }
    }
  }

  resetBoard() {
    this.currentPlayer = this.player1;
    this.player1.resetBoard();
    this.player2.resetBoard();
    this.computerAttacks = [];
    this.startGame();
  }
  startGame() {
    this.container.textContent = "";
    this.createBoard(this.player1, "p1-container");
    this.createBoard(this.player2, "p2-container");
  }
}
const gameC = new gameController();
gameC.startGame();
